const DELICIOUS_IN_DUNGEON_S01E01_LESSON = {"video":{"key":"delicious_in_dungeon_s01e01","series":"Delicious in Dungeon","seriesIcon":"🍲","episodeTitle":"Delicious in Dungeon · Tập 1","icon":"🍲","title":"🍲 Delicious in Dungeon · Tập 1","src":"video/delicious_in_dungeon_s01e01-web-v1.mp4","storageKey":"kino_calibrated_delicious_in_dungeon_s01e01_v1","syncKey":"vokabelgo_kino_perfected_delicious_in_dungeon_s01e01","progressKey":"vokabelgo_kino_progress_delicious_in_dungeon_s01e01","fullDurationStr":"26:47","flashcardDeck":"🎬 Video: Delicious in Dungeon – Tập 1"},"chapterData":{"title":"Delicious in Dungeon · Tập 1","catalogTitle":"Delicious in Dungeon · Tập 1","series":"DELICIOUS IN DUNGEON · TẬP 1","summary":"Sau thất bại trước Rồng Đỏ khiến em gái Falin bị nuốt chửng và cả nhóm mất sạch hành trang, Laios cùng Marcille và Chilchuck quay lại hầm ngục với ý tưởng táo bạo: tự săn quái vật làm lương thực và gặp gỡ đầu bếp người lùn Senshi. Những đoạn chưa rõ lời thoại sẽ tạm để trống phụ đề.","levelLabel":"Gợi ý B1–B2","defaultMode":"light","practiceModeVersion":1,"contentVersion":1,"storageKey":"vokabelgo_kino_chapters_v1_delicious_in_dungeon_s01e01","legacyKey":"vokabelgo_kino_progress_delicious_in_dungeon_s01e01","legacyCount":0,"cueCount":372,"vocabularyCount":16,"chapters":[{"title":"Chuẩn bị đủ rồi, trừ cái bụng","icon":"🐉","start":0,"end":148,"picks":[1200008,1200011,1200012,1200014],"goal":"Kể lại bối cảnh một sự việc, nhận xét về những bất lợi trên đường đi và cảnh báo đồng đội khi gặp nguy hiểm.","practiceUsage":{"1200008":"Khi khẳng định cả nhóm đã chuẩn bị kỹ càng trước một thử thách.","1200011":"Khi nhận xét mọi người đang di chuyển chậm chạp, nặng nề vì mệt hoặc đói.","1200012":"Khi giải thích lý do bị trễ một ngày đường vì nhầm bản đồ.","1200014":"Khi khuyên cả nhóm nên quay về ngay sau khi hoàn thành mục tiêu chính."}},{"title":"Hết tiền mà vẫn phải cứu em","icon":"⚔️","start":148,"end":324,"picks":[1200051,1200054,1200068,1200073],"goal":"Trình bày khó khăn về tài chính và trang bị, bàn chuyện ăn uống và khẳng định sự gắn bó với đồng đội.","practiceUsage":{"1200051":"Khi hỏi ý kiến cả nhóm xem nên chọn món gì cho bữa ăn.","1200054":"Khi nhiệt tình giới thiệu một quán ăn ngon không thể bỏ qua.","1200068":"Khi đồng tình rằng một kế hoạch hoặc giải pháp hoàn toàn có khả năng thành công.","1200073":"Khi nhắc bạn bè đừng coi mình là gánh nặng của cả nhóm."}},{"title":"Đói quá thì ăn… quái vật?","icon":"🍄","start":324,"end":571.9,"picks":[1200095,1200106,1200107,1200133,1200140],"goal":"Đưa ra lập luận thuyết phục người khác, bày tỏ sự phản đối và trao đổi khi thử làm một việc mới.","practiceUsage":{"1200095":"Khi nhấn mạnh tình thế cấp bách và hỏi đối phương có phương án nào tốt hơn không.","1200106":"Khi rủ đồng đội tìm một chỗ thích hợp để dừng chân và nhóm lửa.","1200107":"Khi nhận xét rằng nếu có thêm một vài nguyên liệu nữa thì món ăn sẽ ngon hơn.","1200133":"Khi ghi nhận rằng mình vừa rút ra được một kinh nghiệm hay kiến thức mới.","1200140":"Khi giải thích thông tin mình đọc được trong sách và muốn tự mình kiểm chứng."}},{"title":"May mà có đầu bếp đi ngang","icon":"🍲","start":571.9,"end":789,"picks":[1200145,1200160,1200161,1200178,1200194,1200202],"goal":"Hướng dẫn từng bước sơ chế nguyên liệu, hỏi thăm sau sự cố và chia sẻ niềm đam mê lâu năm.","practiceUsage":{"1200145":"Khi chỉ ra rằng cách chế biến món ăn hiện tại hoàn toàn chưa đúng.","1200160":"Khi nhận xét dụng cụ hiện có quá nhỏ và đề nghị đổi sang đồ dùng của mình.","1200161":"Khi khen ngợi ai đó đã chuẩn bị đồ đạc rất chu đáo.","1200178":"Khi đưa khăn tay cho người đối diện để lau mặt hoặc vết bẩn.","1200194":"Khi giải thích món đồ cần thời gian chuẩn bị nhưng mình đã có sẵn một phần làm xong.","1200202":"Khi dặn mọi người kiên nhẫn chờ thêm một chút trước khi món ăn chín."}},{"title":"Nồi lẩu này ngon thật sao?","icon":"🥣","start":789,"end":958,"picks":[1200206,1200212,1200213,1200226,1200229,1200238,1200239],"goal":"Khen ngợi hương vị món ăn, tự giới thiệu bản thân và xin phép tham gia hoặc chào đón người mới vào nhóm.","practiceUsage":{"1200206":"Khi nhận xét bước đầu rằng món ăn tỏa mùi rất thơm.","1200212":"Khi tấm tắc khen ngợi một món ăn ngon vượt ngoài sức tưởng tượng.","1200213":"Khi người nấu bày tỏ niềm vui vì món ăn hợp khẩu vị của mọi người.","1200226":"Khi sực nhớ ra mọi người đã trò chuyện một lúc mà vẫn chưa giới thiệu tên tuổi.","1200229":"Khi hỏi thăm xem đối phương đến một nơi nào đó vì mục đích gì.","1200238":"Khi lịch sự xin phép được tham gia đồng hành cùng một nhóm.","1200239":"Khi vui vẻ nhận lời và khẳng định sự góp mặt của đối phương sẽ giúp ích rất nhiều."}},{"title":"Nói ăn gì cũng được, nhưng…","icon":"🌿","start":958,"end":1155,"picks":[1200255,1200256,1200269,1200286,1200301],"goal":"Đề xuất nghỉ ngơi khi mệt mỏi, hỏi ý kiến chọn món ăn và giải thích đặc điểm của một loài thực vật.","practiceUsage":{"1200255":"Khi nhận xét cả nhóm đã đi đường dài và ai nấy đều thấm mệt.","1200256":"Khi rủ mọi người tìm chỗ dừng chân qua đêm để nghỉ ngơi.","1200269":"Khi nói rằng mình không kén chọn, miễn là món đó ăn được.","1200286":"Khi nhận lỗi sau lúc tranh luận và thừa nhận người kia nói đúng.","1200301":"Khi trấn an đồng đội rằng khu vực hiện tại vẫn còn an toàn."}},{"title":"Đừng hái quá phần mình cần","icon":"🌺","start":1155,"end":1270,"picks":[1200314,1200320,1200326,1200330],"goal":"Nhắc nhở nguyên tắc chỉ lấy đủ dùng, hướng dẫn cách xử lý tình huống khẩn cấp và cảm ơn người đã cứu giúp.","practiceUsage":{"1200314":"Khi giục người khác gác lại chuyện lý thuyết vì tình thế đang khẩn cấp.","1200320":"Khi giải thích rằng đặc điểm hoặc kết quả còn tùy thuộc vào từng loại cụ thể.","1200326":"Khi khuyên nên tập trung xử lý dứt điểm vào một chỗ thay vì dàn trải.","1200330":"Khi bày tỏ lòng biết ơn chân thành sau khi được bạn bè giúp đỡ."}},{"title":"Bánh tart từ cây ăn thịt","icon":"🥧","start":1270,"end":1607.488,"picks":[1200352,1200355,1200368,1200375,1200378],"goal":"Mô tả quy trình nấu nướng trong bếp, mời bạn bè nếm thử món mới và bàn cách giải quyết một việc khó xử.","practiceUsage":{"1200352":"Khi hoàn tất việc nấu nướng và gọi mọi người vào dùng bữa.","1200355":"Khi nhận xét hương vị món ăn mặn mà và khác hẳn hình dung ban đầu.","1200368":"Khi gật gù vì vừa hiểu ra quy luật hoặc cách vận hành của một sự việc.","1200375":"Khi khuyên ngăn không nên mạo hiểm làm việc gì đó vì dễ xảy ra rủi ro.","1200378":"Khi nhấn mạnh rằng cần đặt một vật ở vị trí thật dễ nhận thấy."}}]},"flashcards":[{"id":"vk_delicious_in_dungeon_s01e01_schwerfallig","term":"schwerfällig","meaning":"nặng nề; chậm chạp","grammar":"Tính từ/trạng từ: di chuyển thiếu linh hoạt vì mệt hoặc đói.","example":"Wir bewegen uns alle so schwerfällig.","exampleVi":"Tất cả chúng ta đều đang di chuyển quá nặng nề.","note":"Laios nhận ra cả nhóm cử động nặng nề vì bị đói trong trận đánh Rồng Đỏ.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200011,"sourceUrl":"?kino=dungeon&part=1"},{"id":"vk_delicious_in_dungeon_s01e01_etwas_vergeuden","term":"etwas vergeuden","meaning":"lãng phí (thời gian, công sức)","grammar":"Động từ không tách: vergeudet; vergeudete; hat vergeudet + Akk.","example":"Auf dem Weg hierher haben wir einen Tag wegen eines Fehlers auf der Karte vergeudet.","exampleVi":"Trên đường đến đây, chúng ta đã lãng phí mất một ngày vì một lỗi trên bản đồ.","note":"Đi với danh từ chỉ thời gian hoặc tiền bạc (einen Tag / Zeit / Geld vergeuden).","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200012,"sourceUrl":"?kino=dungeon&part=1"},{"id":"vk_delicious_in_dungeon_s01e01_die_ausrustung","term":"die Ausrüstung","meaning":"trang bị; đồ nghề","grammar":"die Ausrüstung, die Ausrüstungen (f.).","example":"Es ist so, wir haben unsere ganze Ausrüstung im Dungeon zurückgelassen.","exampleVi":"Chuyện là chúng ta đã bỏ lại toàn bộ trang bị ở dưới hầm ngục rồi.","note":"Danh từ giống cái đuôi -ung, chỉ toàn bộ vũ khí và hành trang của nhóm mạo hiểm giả.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200031,"sourceUrl":"?kino=dungeon&part=2"},{"id":"vk_delicious_in_dungeon_s01e01_jemanden_abwerben","term":"jemanden abwerben","meaning":"lôi kéo, chiêu mộ người của nhóm khác","grammar":"Động từ tách: wirbt ab; warb ab; hat abgeworben + Akk.","example":"Andere Gilden versuchen wohl schon seit einer Weile, sie abzuwerben.","exampleVi":"Các hội khác có lẽ đã tìm cách lôi kéo họ suốt một thời gian rồi.","note":"Chilchuck giải thích lý do hai thành viên cũ rời nhóm để sang hội khác.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200038,"sourceUrl":"?kino=dungeon&part=2"},{"id":"vk_delicious_in_dungeon_s01e01_ein_klotz_am_bein_sein","term":"ein Klotz am Bein sein","meaning":"là cục nợ; là gánh nặng ngáng chân","grammar":"Thành ngữ cố định: jemandem (Dat.) ein Klotz am Bein sein.","example":"Sag ja nicht, dass ich ein Klotz am Bein bin.","exampleVi":"Đừng có mà nói tớ là cục nợ ngáng chân đấy nhé.","note":"Marcille khẳng định cô là pháp sư tài giỏi chứ không phải gánh nặng của Laios.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200073,"sourceUrl":"?kino=dungeon&part=2"},{"id":"vk_delicious_in_dungeon_s01e01_von_etwas_wimmeln","term":"von etwas wimmeln","meaning":"lúc nhúc; đầy rẫy thứ gì","grammar":"Cấu trúc: es wimmelt (in/an + Dat.) vor/von + Dat.","example":"Im Dungeon wimmelt es nur so vor Monstern.","exampleVi":"Trong hầm ngục lúc nhúc đầy rẫy những quái vật.","note":"Cụm \"nur so vor Monstern wimmeln\" nhấn mạnh số lượng quái vật dày đặc.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200080,"sourceUrl":"?kino=dungeon&part=3"},{"id":"vk_delicious_in_dungeon_s01e01_die_lebensmittelvergiftung","term":"die Lebensmittelvergiftung","meaning":"ngộ độc thực phẩm","grammar":"die Lebensmittelvergiftung, -en (f.).","example":"Und wie man hört, haben die ständig eine Lebensmittelvergiftung.","exampleVi":"Mà nghe nói bọn họ còn bị ngộ độc thực phẩm suốt ngày nữa cơ.","note":"Danh từ ghép từ das Lebensmittel (thực phẩm) và die Vergiftung (sự ngộ độc).","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200092,"sourceUrl":"?kino=dungeon&part=3"},{"id":"vk_delicious_in_dungeon_s01e01_sich_den_magen_verderben","term":"sich den Magen verderben","meaning":"bị đau bụng; ăn phải đồ hỏng","grammar":"Cụm phản thân với Dativ: sich (Dat.) den Magen verderben.","example":"Alles wäre umsonst, wenn wir uns den Magen verderben und nicht mehr kämpfen können.","exampleVi":"Mọi công sức sẽ đổ sông đổ bể hết nếu chúng ta đau bụng và không thể chiến đấu được nữa.","note":"Marcille lo việc ăn quái vật bừa bãi sẽ khiến cả nhóm đau bụng không chiến đấu nổi.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200096,"sourceUrl":"?kino=dungeon&part=3"},{"id":"vk_delicious_in_dungeon_s01e01_abgegriffen","term":"abgegriffen","meaning":"cũ sờn; sờn gáy (vì dùng nhiều)","grammar":"Tính từ phân từ II của abgreifen.","example":"Was ist das für ein Buch? Sieht ganz schön abgegriffen aus.","exampleVi":"Cuốn sách gì thế kia? Trông cũ nát sờn gáy cả rồi.","note":"Chilchuck nhận xét về cuốn Cẩm nang Ẩm thực Hầm ngục đã sờn cũ của Laios.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200105,"sourceUrl":"?kino=dungeon&part=3"},{"id":"vk_delicious_in_dungeon_s01e01_die_zubereitung","term":"die Zubereitung","meaning":"cách chế biến; việc sơ chế nấu nướng","grammar":"die Zubereitung, die Zubereitungen (f.), từ động từ tách zubereiten.","example":"Die Art der Zubereitung ist völlig falsch.","exampleVi":"Cách chế biến như thế này là sai hoàn toàn rồi.","note":"Từ khóa trung tâm trong các cảnh nấu ăn của Senshi suốt tập phim.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200145,"sourceUrl":"?kino=dungeon&part=4"},{"id":"vk_delicious_in_dungeon_s01e01_nicht_in_frage_kommen","term":"nicht in Frage kommen","meaning":"không thể chấp nhận được; không bàn tới","grammar":"Cụm cố định: etwas kommt (überhaupt) nicht in Frage.","example":"Kommt überhaupt nicht in Frage! Hör mal, das hier ist ein Friedhof!","exampleVi":"Không đời nào chấp nhận được! Nghe này, nơi đây là một nghĩa trang đấy!","note":"Cách phản đối dứt khoát khi ai đó đưa ra một đề nghị vô lý.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200165,"sourceUrl":"?kino=dungeon&part=4"},{"id":"vk_delicious_in_dungeon_s01e01_die_delikatesse","term":"die Delikatesse","meaning":"món ngon thượng hạng; cao lương mỹ vị","grammar":"die Delikatesse, die Delikatessen (f.).","example":"So wird der Schleim zur Delikatesse.","exampleVi":"Làm như vậy thì Slime sẽ trở thành một món cao lương mỹ vị.","note":"Senshi giải thích cách sơ chế và phơi khô để biến Slime thành đặc sản.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200189,"sourceUrl":"?kino=dungeon&part=4"},{"id":"vk_delicious_in_dungeon_s01e01_sich_jemandem_anschliessen","term":"sich jemandem anschließen","meaning":"gia nhập; đi cùng với ai","grammar":"Động từ tách phản thân + Dativ: schließt sich an; hat sich angeschlossen.","example":"Bitte, erlaubst du, dass ich mich euch anschließe?","exampleVi":"Xin hỏi, cậu có cho phép tôi gia nhập đi cùng nhóm của các cậu không?","note":"Senshi xin phép nhập bọn cùng nhóm Laios để xuống tầng sâu nấu Rồng Đỏ.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200238,"sourceUrl":"?kino=dungeon&part=5"},{"id":"vk_delicious_in_dungeon_s01e01_rumnorgeln","term":"rumnörgeln","meaning":"cằn nhằn; chê ỏng chê eo","grammar":"Động từ tách thông tục: nörgelt rum; hat rumgenörgelt.","example":"Und wenn man Vorschläge macht, wird immer nur rumgenörgelt.","exampleVi":"Thế mà đến lúc người ta gợi ý cho thì lại chỉ toàn cằn nhằn chê bai.","note":"Tiền tố rum- (herum-) mang sắc thái khẩu ngữ chỉ hành động lặp đi lặp lại gây bực mình.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200281,"sourceUrl":"?kino=dungeon&part=6"},{"id":"vk_delicious_in_dungeon_s01e01_taktlos","term":"taktlos","meaning":"vô duyên; thiếu tinh tế; kém tế nhị","grammar":"Tính từ: taktlos (trái nghĩa với taktvoll).","example":"Na ja, selbst ich fand das gerade etwas taktlos.","exampleVi":"Thôi đi, ngay cả tôi nghe câu vừa rồi cũng thấy hơi vô duyên đấy.","note":"Chilchuck phê bình Laios khi cậu hào hứng hỏi cảm giác của Marcille lúc vừa bị cây quấn.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200339,"sourceUrl":"?kino=dungeon&part=7"},{"id":"vk_delicious_in_dungeon_s01e01_sofort_ins_auge_fallen","term":"sofort ins Auge fallen","meaning":"đập ngay vào mắt; dễ nhận thấy ngay","grammar":"Thành ngữ: jemandem (Dat.) ins Auge fallen (fällt; fiel; ist gefallen).","example":"Er muss sofort ins Auge fallen.","exampleVi":"Phải đặt sao cho người ta nhìn thấy ngay lập tức.","note":"Nhóm Laios đặt xác nhà mạo hiểm giả ở vị trí dễ thấy để đội cứu hộ đi qua nhận ra.","deck":"🎬 Video: Delicious in Dungeon – Tập 1","tags":["Video","Delicious in Dungeon"],"videoKey":"delicious_in_dungeon_s01e01","cueId":1200378,"sourceUrl":"?kino=dungeon&part=8"}]};
