const FRIEREN_S01E02_LESSON = {"video":{"key":"frieren_s01e02","series":"Frieren","seriesIcon":"🪄","episodeTitle":"Frieren · Tập 2","icon":"🪄","title":"🪄 Frieren · Tập 2","src":"video/frieren_s01e02-web-v1.mp4","storageKey":"kino_calibrated_frieren_s01e02_v1","syncKey":"vokabelgo_kino_perfected_frieren_s01e02","progressKey":"vokabelgo_kino_progress_frieren_s01e02","fullDurationStr":"26:00","flashcardDeck":"🎬 Video: Frieren – Tập 2"},"chapterData":{"title":"Frieren · Tập 2","catalogTitle":"Frieren · Tập 2","series":"FRIEREN · TẬP 2","summary":"Frieren hướng dẫn Fern luyện tập phép thuật trong khi giải mã cuốn ma đạo thư của Ewig cho Heiter. Trước khi Heiter qua đời, Fern kịp chứng minh bản thân đã có thể tự lập và cùng Frieren lên đường phiêu lưu, cùng nhau tìm kiếm loài cỏ trăng xanh quê hương để tô điểm cho bức tượng của dũng sĩ Himmel. Những đoạn chưa rõ lời thoại sẽ tạm để trống phụ đề.","levelLabel":"Gợi ý B1–B2","defaultMode":"light","practiceModeVersion":1,"contentVersion":1,"storageKey":"vokabelgo_kino_chapters_v1_frieren_s01e02","legacyKey":"vokabelgo_kino_progress_frieren_s01e02","legacyCount":0,"cueCount":243,"vocabularyCount":18,"chapters":[{"title":"Bài học phép thuật tầm xa và bốn năm rèn luyện của Fern","icon":"🪄","start":0,"end":248,"picks":[1300011,1300012,1300013,1300015,1300016,1300017,1300018],"goal":"Giải thích các yếu tố cốt lõi khi hướng dẫn kỹ năng, động viên người mới học và trao đổi về tiến độ rèn luyện.","practiceUsage":{"1300011":"Khi trấn an người học rằng đa số mọi người đều gặp khó khăn ở bước này.","1300012":"Khi khuyên đối phương cứ yên tâm và không cần phải lo lắng.","1300013":"Khi khích lệ rằng với năng lực của đối phương thì việc học sẽ nhanh hơn.","1300015":"Khi hỏi thăm tiến độ hướng dẫn hoặc đào tạo một học viên.","1300016":"Khi khen ngợi ai đó tiến bộ vượt bậc trong thời gian ngắn.","1300017":"Khi nhận xét một người đang quá lao tâm khổ tứ vào công việc.","1300018":"Khi lưu ý rằng sự thái quá đôi khi lại mang đến hệ quả không tốt."}},{"title":"Khi Heiter ngã bệnh và lời tri ân của Fern","icon":"🙏","start":248,"end":496,"picks":[1300026,1300028,1300029,1300034,1300054,1300059,1300061],"goal":"An ủi người đang buồn, bày tỏ lòng biết ơn sâu sắc và khích lệ ai đó hành động theo điều họ cho là đúng.","practiceUsage":{"1300026":"Khi nhẹ nhàng an ủi người đối diện đừng giữ vẻ mặt buồn bã.","1300028":"Khi hứa sẽ đẩy nhanh tiến độ giải quyết một công việc quan trọng.","1300029":"Khi nói lời cảm ơn thân mật và trìu mến với một người bạn quý.","1300034":"Khi khẳng định chắc chắn đối phương sẽ đạt được mục tiêu vào một ngày không xa.","1300054":"Khi bày tỏ quyết tâm sống tốt để người cưu mang mình không bao giờ phải hối tiếc.","1300059":"Khi kiểm tra lại xem học trò còn nhớ kỹ những kiến thức đã được dạy hay không.","1300061":"Khi trao quyền tự quyết và ủng hộ đối phương làm điều họ tin là đúng."}},{"title":"Mưu mẹo cuối đời của Heiter và cuộc chia ly ấm áp","icon":"🌅","start":496,"end":680,"picks":[1300063,1300068,1300071,1300074,1300080,1300082,1300087],"goal":"Đánh giá trình độ chuyên môn, nhờ cậy chăm sóc người thân và khuyên nhủ lời từ biệt chân thành.","practiceUsage":{"1300063":"Khi nhận xét ai đó đã giỏi nhưng vẫn cần rèn giũa thêm đôi chút cho hoàn thiện.","1300068":"Khi lịch sự nhờ một người đáng tin cậy đưa ai đó đồng hành cùng.","1300071":"Khi nhận ra mình vừa bị bạn bè dùng mẹo gài vào thế đã rồi.","1300074":"Khi hỏi thẳng đối phương đang có ý định hay kế hoạch gì.","1300080":"Khi khuyên ai đó hãy nói lời chia tay đàng hoàng và trọn vẹn với người thân.","1300082":"Khi chân thành khen ngợi sự tử tế và tấm lòng nhân hậu của một người bạn.","1300087":"Khi mở lời bày tỏ sự biết ơn sâu sắc đối với người đã giúp đỡ mình."}},{"title":"Sở thích sưu tầm phép thuật kỳ lạ trên đường phiêu lưu","icon":"🍵","start":680,"end":770,"picks":[1300092,1300093,1300096,1300098,1300102,1300105,1300110],"goal":"Thông báo hoàn thành công việc, trao đổi về phần thưởng, chia sẻ sở thích cá nhân và nhờ cậy lịch sự.","practiceUsage":{"1300092":"Khi báo hiệu công việc đã hoàn tất và mọi người có thể dừng tay.","1300093":"Khi cảm ơn người đã giúp đỡ mình và trao phần thưởng như đã hẹn.","1300096":"Khi hỏi đồng đội xem thù lao nhận được sau chuyến công việc lần này là gì.","1300098":"Khi rủ bạn bè để lát nữa hãy đem một món đồ hay kỹ năng mới ra thử nghiệm.","1300102":"Khi giải thích nhẹ nhàng rằng việc sưu tầm một thứ gì đó đơn giản là thú vui cá nhân.","1300105":"Khi trả lời vừa phải, linh hoạt về mức độ yêu thích hoặc cảm xúc của mình.","1300110":"Khi trang trọng mở lời nhờ người khác giúp mình một công việc."}},{"title":"Bức tượng rỉ sét của Himmel và loài cỏ trăng xanh quê hương","icon":"🗿","start":770,"end":947,"picks":[1300117,1300127,1300128,1300130,1300135,1300136,1300146],"goal":"Mô tả tình trạng xuống cấp của đồ vật, kể lại kỷ niệm hài hước về bạn cũ và bắt tay vào việc dọn dẹp.","practiceUsage":{"1300117":"Khi nhận xét một công trình hay đồ vật đã bị hư hại, xuống cấp nặng nề.","1300127":"Khi nói thẳng rằng kết quả hiện tại là do chính người đó tự chuốc lấy.","1300128":"Khi nhắc lại tính cách thích làm tâm điểm chú ý của một người bạn.","1300130":"Khi hào hứng hỏi bạn bè xem tư thế tạo dáng của mình trông đã đẹp chưa.","1300135":"Khi xắn tay áo rủ mọi người cùng bắt đầu dọn dẹp sạch sẽ một khu vực.","1300136":"Khi bày tỏ sự cảm kích vì đối phương đã giúp đỡ mình vô cùng đắc lực.","1300146":"Khi thừa nhận mình không biết vì chưa từng tận mắt nhìn thấy thứ đó bao giờ."}},{"title":"Nửa năm tìm kiếm cỏ trăng xanh và nỗi trăn trở của Fern","icon":"🌿","start":947,"end":1145,"picks":[1300158,1300159,1300164,1300168,1300172,1300176,1300189],"goal":"Hỏi khéo khi thấy người khác giấu chuyện, bàn bạc mở rộng phạm vi tìm kiếm và lắng nghe góc nhìn của người từng trải.","practiceUsage":{"1300158":"Khi tinh ý nhận ra người đối diện đang lén giấu mình một chuyện gì đó.","1300159":"Khi trấn an đối phương cứ đưa ra cho mình xem vì mình sẽ không giận đâu.","1300164":"Khi hỏi lại để xác nhận xem đề xuất táo bạo của đối phương có phải là thật không.","1300168":"Khi khẳng định một mục tiêu rất xứng đáng để bỏ công sức tìm kiếm.","1300172":"Khi thành thật chia sẻ rằng mình làm việc này vì tâm nguyện của chính bản thân.","1300176":"Khi đề xuất mở rộng phạm vi tìm kiếm sau một thời gian chưa có kết quả.","1300189":"Khi nhắc người nghe nhìn nhận sự việc từ góc độ và trải nghiệm của người khác."}},{"title":"Lần theo dấu chuột hạt giống và lý do ngốc nghếch của Frieren","icon":"🐿️","start":1145,"end":1335,"picks":[1300194,1300195,1300198,1300201,1300203,1300204,1300205],"goal":"Thể hiện sự thấu hiểu tâm tư của người đồng hành, đề nghị kiên trì thêm một chút và kể về động lực cá nhân.","practiceUsage":{"1300194":"Khi nhận xét người đồng hành đang suy nghĩ và lo lắng rất chu toàn.","1300195":"Khi bày tỏ sự đồng cảm rằng mình hiểu rõ điều đối phương đang bận tâm.","1300198":"Khi xin phép được kiên trì nán lại tìm kiếm thêm một chút thời gian nữa.","1300201":"Khi hỏi thẳng xem đối phương có thực sự định dừng cuộc tìm kiếm hay không.","1300203":"Khi ra hiệu cho đồng đội lập tức bám theo dấu vết vừa phát hiện.","1300204":"Khi nói khiêm tốn rằng công việc mình đang làm chỉ là thú vui giết thời gian.","1300205":"Khi phản biện rằng hành động thực tế của đối phương nghiêm túc hơn lời họ nói nhiều."}},{"title":"Đồi hoa trăng xanh nở rộ: Không nhất thiết phải là phép thuật","icon":"🌸","start":1335,"end":1560.102313,"picks":[1300222,1300223,1300226,1300233,1300234,1300237,1300243],"goal":"Hẹn ước cho tương lai, chia sẻ niềm vui khi tìm thấy điều quý giá và chiêm nghiệm về con đường mình đã chọn.","practiceUsage":{"1300222":"Khi hứa hẹn một ngày nào đó sẽ đưa người bạn đồng hành đến ngắm một cảnh đẹp.","1300223":"Khi nhẹ nhàng nhận lời hẹn ước với thái độ tùy duyên nếu có cơ hội.","1300226":"Khi vỡ òa thông báo rằng cả nhóm đã thực sự tìm thấy thứ mình hằng kiếm tìm.","1300233":"Khi bộc bạch rằng phương tiện ban đầu không quan trọng bằng mục đích tự lập.","1300234":"Khi nhắc nhở ai đó trân trọng con đường mà chính họ đã gắn bó và lựa chọn.","1300237":"Khi trầm trồ khen ngợi một khung cảnh thiên nhiên đẹp rực rỡ trước mắt.","1300243":"Khi rủ người đồng hành tiếp tục lên đường sau khi đã hoàn thành tâm nguyện."}}]},"flashcards":[{"id":"vk_frieren_s01e02_von_heute_auf_morgen","term":"von heute auf morgen","meaning":"trong ngày một ngày hai; ngay tức khắc","grammar":"Cụm trạng ngữ chỉ thời gian, thường đi với phủ định (nicht von heute auf morgen).","example":"So was lässt sich nicht von heute auf morgen beheben.","exampleVi":"Chuyện như vậy không thể khắc phục chỉ trong ngày một ngày hai được.","note":"Frieren giải thích cho Fern rằng việc kiểm soát và giải phóng ma lực cần nhiều năm luyện tập.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300008,"sourceUrl":"?kino=frieren2&part=1"},{"id":"vk_frieren_s01e02_etwas_fur_etwas_aufwenden","term":"etwas (für etwas) aufwenden","meaning":"bỏ ra, dành ra (thời gian, công sức)","grammar":"Động từ tách: wendet auf; wandte auf / wendete auf; hat aufgewendet + Akk.","example":"Man braucht nicht nur Talent, sondern muss auch viele Jahre Übung dafür aufwenden.","exampleVi":"Người ta không chỉ cần thiên phú mà còn phải bỏ ra rất nhiều năm khổ luyện cho việc đó.","note":"Cấu trúc \"Zeit / Mühe / Übung für etwas aufwenden\" rất hay dùng khi nói về rèn luyện kỹ năng.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300009,"sourceUrl":"?kino=frieren2&part=1"},{"id":"vk_frieren_s01e02_mit_etwas_vorankommen","term":"mit etwas vorankommen","meaning":"tiến triển; đạt tiến độ với việc gì","grammar":"Động từ tách: kommt voran; kam voran; ist vorangekommen.","example":"Wie kommst du mit Ferns Ausbildung voran?","exampleVi":"Việc huấn luyện cho Fern của cậu tiến triển thế nào rồi?","note":"Heiter hỏi thăm Frieren về tiến độ huấn luyện phép thuật cho Fern sau bốn năm.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300015,"sourceUrl":"?kino=frieren2&part=1"},{"id":"vk_frieren_s01e02_sich_in_etwas_reinsteigern","term":"sich in etwas reinsteigern","meaning":"lao đầu vào; đắm chìm quá mức vào việc gì","grammar":"Động từ tách phản thân khẩu ngữ (hineinsteigern): steigert sich rein.","example":"Sie steigert sich da zu sehr rein.","exampleVi":"Con bé lao đầu vào tập luyện quá mức.","note":"Frieren nhận xét Fern tập luyện quá sức trong rừng vì muốn sớm tự lập trước khi Heiter qua đời.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300017,"sourceUrl":"?kino=frieren2&part=1"},{"id":"vk_frieren_s01e02_sich_verkriechen","term":"sich verkriechen","meaning":"trốn vào; thu mình vào góc kín","grammar":"Động từ không tách phản thân: verkriecht sich; verkroch sich; hat sich verkrochen.","example":"In letzter Zeit verkriecht sie sich sehr oft in den Wald, oder?","exampleVi":"Dạo gần đây con bé rất hay trốn vào trong rừng một mình, phải không?","note":"Heiter để ý thấy Fern thường xuyên vào rừng sâu một mình để luyện tập bắn xuyên tảng đá.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300019,"sourceUrl":"?kino=frieren2&part=1"},{"id":"vk_frieren_s01e02_zusammenbrechen","term":"zusammenbrechen","meaning":"ngã quỵ; suy sụp; đổ sập","grammar":"Động từ tách (sein): bricht zusammen; brach zusammen; ist zusammengebrochen.","example":"Heiter ist zusammengebrochen.","exampleVi":"Heiter vừa ngã bệnh rồi.","note":"Frieren thông báo cho Fern tạm dừng buổi tập vì Heiter vừa ngã bệnh trên bàn trà.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300031,"sourceUrl":"?kino=frieren2&part=2"},{"id":"vk_frieren_s01e02_aufrichtig_und_geradlinig","term":"aufrichtig und geradlinig","meaning":"chân thành và ngay thẳng","grammar":"Cặp tính từ miêu tả phẩm chất tính cách con người.","example":"Er war anders als ich, aufrichtig und geradlinig.","exampleVi":"Cậu ấy khác hẳn với ta, là một người chân thành và ngay thẳng.","note":"Heiter kể cho Fern nghe về phẩm chất cao đẹp của người bạn quá cố là dũng sĩ Himmel.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300042,"sourceUrl":"?kino=frieren2&part=2"},{"id":"vk_frieren_s01e02_unwiederbringlich","term":"unwiederbringlich","meaning":"vĩnh viễn không thể lấy lại được; một đi không trở lại","grammar":"Tính từ / trạng từ ghép: un- + wieder- + bringen + -lich.","example":"genauso wie meine wundervollen Erinnerungen, unwiederbringlich aus dieser Welt verschwinden.","exampleVi":"cũng như những ký ức tuyệt đẹp của ta, sẽ vĩnh viễn biến mất khỏi thế giới này.","note":"Heiter nhận ra nếu mình chết đi mà không truyền lại ký ức về Himmel thì mọi thứ sẽ biến mất mãi mãi.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300049,"sourceUrl":"?kino=frieren2&part=2"},{"id":"vk_frieren_s01e02_allein_zurechtkommen","term":"allein zurechtkommen","meaning":"tự xoay xở được; tự lo liệu ổn thỏa","grammar":"Động từ tách (sein): kommt zurecht; kam zurecht; ist zurechtgekommen.","example":"und wissen, dass ich allein zurechtkomme.","exampleVi":"và yên tâm biết rằng em có thể tự lo liệu được một mình.","note":"Fern quyết tâm trở thành pháp sư thực thụ để Heiter yên tâm rằng cô có thể tự sống tốt.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300058,"sourceUrl":"?kino=frieren2&part=2"},{"id":"vk_frieren_s01e02_der_feinschliff","term":"der Feinschliff","meaning":"sự mài giũa hoàn thiện bước cuối","grammar":"der Feinschliff (m., thường dùng số ít): einen gewissen Feinschliff benötigen.","example":"Sie benötigt noch einen gewissen Feinschliff.","exampleVi":"Con bé vẫn còn cần mài giũa thêm đôi chút.","note":"Nghĩa gốc là mài bóng đá quý/kim loại, nghĩa bóng chỉ bước trau chuốt cuối cùng cho kỹ năng.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300063,"sourceUrl":"?kino=frieren2&part=3"},{"id":"vk_frieren_s01e02_jemanden_reinlegen","term":"jemanden reinlegen","meaning":"gài bẫy; lừa ai vào tròng","grammar":"Động từ tách khẩu ngữ (hineinlegen): legt rein; legte rein; hat reingelegt + Akk.","example":"Du hast mich reingelegt, Heiter.","exampleVi":"Cậu đã gài bẫy tôi đấy à, Heiter.","note":"Frieren nhận ra Heiter giả vờ muốn đuổi hai cô trò đi trong đêm để buộc Frieren nhận lời dẫn Fern theo.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300071,"sourceUrl":"?kino=frieren2&part=3"},{"id":"vk_frieren_s01e02_jemanden_hinter_das_licht_fuhren","term":"jemanden hinter das Licht führen","meaning":"dắt mũi; đánh lừa ai","grammar":"Thành ngữ cố định: jemanden hinter das Licht / hinters Licht führen.","example":"Ich wurde doch einfach nur hinter das Licht geführt.","exampleVi":"Tôi chẳng qua chỉ bị dắt mũi mà thôi.","note":"Frieren mỉm cười nói về màn kịch khéo léo của \"lão linh mục đạo mạo\" Heiter.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300089,"sourceUrl":"?kino=frieren2&part=3"},{"id":"vk_frieren_s01e02_im_rampenlicht_stehen","term":"im Rampenlicht stehen","meaning":"đứng dưới ánh đèn sân khấu; là tâm điểm chú ý","grammar":"Cụm cố định: im Rampenlicht stehen (das Rampenlicht: ánh đèn sân khấu).","example":"Er wollte doch immer im Rampenlicht stehen.","exampleVi":"Lúc nào cậu ta chẳng muốn mình là tâm điểm của sự chú ý.","note":"Frieren nhớ lại tính cách thích tạo dáng và muốn lưu lại dấu ấn của dũng sĩ Himmel.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300128,"sourceUrl":"?kino=frieren2&part=5"},{"id":"vk_frieren_s01e02_jemanden_zur_weissglut_bringen","term":"jemanden zur Weißglut bringen","meaning":"làm ai phát điên; chọc ai tức sôi máu","grammar":"Thành ngữ: die Weißglut (nhiệt độ nung sắt nóng trắng) -> zur Weißglut bringen.","example":"Er hat 18 Stunden lang über seine Pose gegrübelt und alle zur Weißglut gebracht.","exampleVi":"Cậu ta đã đắn đo suốt mười tám tiếng đồng hồ chỉ để chọn tư thế đứng và làm tất cả mọi người phát điên lên.","note":"Himmel từng đắn đo suốt 18 tiếng đồng hồ chỉ để chọn tư thế dựng tượng khiến cả nhóm phát rồ.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300131,"sourceUrl":"?kino=frieren2&part=5"},{"id":"vk_frieren_s01e02_jemandem_etwas_verheimlichen","term":"jemandem etwas verheimlichen","meaning":"giấu giếm ai chuyện gì","grammar":"Động từ không tách: verheimlicht; verheimlichte; hat verheimlicht + Dat. + Akk.","example":"Du verheimlichst mir doch was.","exampleVi":"Bà đang giấu tôi chuyện gì đó phải không.","note":"Frieren bắt gặp bà lão thảo dược đang giấu mấy con chuột hạt giống ở sau lưng.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300158,"sourceUrl":"?kino=frieren2&part=6"},{"id":"vk_frieren_s01e02_den_suchradius_erweitern","term":"den Suchradius erweitern","meaning":"mở rộng phạm vi tìm kiếm","grammar":"der Suchradius, die Suchradien (m.) + erweitern (mở rộng).","example":"Wir sollten so langsam den Suchradius erweitern.","exampleVi":"Có lẽ đã đến lúc chúng ta nên mở rộng phạm vi tìm kiếm ra.","note":"Sau nửa năm tìm kiếm cỏ trăng xanh quanh rừng chưa thấy, Frieren đề nghị mở rộng bán kính dò tìm.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300176,"sourceUrl":"?kino=frieren2&part=6"},{"id":"vk_frieren_s01e02_beharrlich","term":"beharrlich","meaning":"kiên trì; bền bỉ; cố chấp theo đuổi","grammar":"Tính từ / trạng từ từ động từ beharren (kiên định giữ vững).","example":"Frieren kann extrem beharrlich sein, wenn es um einen Zauber geht.","exampleVi":"Cô Frieren có thể cực kỳ cố chấp mỗi khi liên quan đến chuyện phép thuật.","note":"Fern tâm sự với bà lão thảo dược về sự kiên nhẫn không màng năm tháng của Frieren khi săn tìm phép thuật.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300182,"sourceUrl":"?kino=frieren2&part=6"},{"id":"vk_frieren_s01e02_der_zeitvertreib","term":"der Zeitvertreib","meaning":"thú tiêu khiển; trò giết thời gian","grammar":"der Zeitvertreib, die Zeitvertreibe (m.).","example":"Das ist nur ein Zeitvertreib.","exampleVi":"Đó chỉ là một thú tiêu khiển giết thời gian thôi.","note":"Frieren gọi việc sưu tầm phép thuật vặt là thú tiêu khiển, nhưng thực chất bắt nguồn từ lời khen của Himmel.","deck":"🎬 Video: Frieren – Tập 2","tags":["Video","Frieren"],"videoKey":"frieren_s01e02","cueId":1300204,"sourceUrl":"?kino=frieren2&part=7"}]};
